INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Bearbeiten von Fehlern ein zentraler Bestandteil des Fehlermanagements?', 2, '[{"text": "Ja", "correct": true, "because": "Löst Probleme"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Bearbeiten von Fehlern?', 3, '[{"text": "Projektqualität und Fortschritt sichern", "correct": true, "because": "Beseitigt Hindernisse"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerbearbeitung behebt Probleme. b) Sie erfolgt nur im Abschluss.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Fehlerbearbeitung?', 4, '[{"text": "Fehler identifizieren", "correct": true, "because": "Erster Schritt"}, {"text": "Unklare Lösungen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Fehler beheben", "correct": true, "because": "Löst Problem"}, {"text": "Lösung dokumentieren", "correct": true, "because": "Sichert Nachweis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Fehlerbearbeitung erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Probleme bleiben ungelöst"}, {"text": "Ja", "correct": false, "because": "Qualität leidet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Fehlerbearbeitung in der Durchführung?', 3, '[{"text": "Störungen beseitigen", "correct": true, "because": "Sichert Ablauf"}, {"text": "Projekt neu planen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Team finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fehlerbearbeitung nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte haben Fehler"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat das Team bei der Fehlerbearbeitung?', 3, '[{"text": "Fehler beheben und melden", "correct": true, "because": "Sichert Qualität"}, {"text": "Projektziele allein festlegen", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerbearbeitung erfordert Analyse. b) Sie ist nur für technische Fehler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch organisatorisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Fehlerbearbeitung?', 3, '[{"text": "Qualität und Fortschritt leiden", "correct": true, "because": "Probleme bleiben"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Nacharbeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Fehlerbearbeitung ohne Dokumentation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Nachweis und Lernen fehlen"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Fehlerbearbeitung?', 3, '[{"text": "Bug in Software beheben", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas reparieren", "correct": false, "because": "Zu vage"}, {"text": "Team soll Fehler ignorieren", "correct": false, "because": "Keine Bearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fehlerbearbeitung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team führt aus"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Fehlerbearbeitung wichtig?', 4, '[{"text": "Fehlerbeschreibung", "correct": true, "because": "Definiert Problem"}, {"text": "Unklare Lösung", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Lösungsstrategie", "correct": true, "because": "Behebt Fehler"}, {"text": "Priorisierung", "correct": true, "because": "Bestimmt Dringlichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Fehlerbearbeitung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Fehlerbearbeitung?', 3, '[{"text": "Ticketsystem", "correct": true, "because": "Verfolgt Fehler"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Fehlerbearbeitung ohne Team erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Team behebt Fehler"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Fehlerbearbeitung?', 3, '[{"text": "Fehlende Fehlerinformationen", "correct": true, "because": "Verhindern Lösung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerbearbeitung sichert Qualität. b) Sie ist nur für Softwarefehler.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Fehlerbearbeitung?', 3, '[{"text": "Verbesserte Projektergebnisse", "correct": true, "because": "Beseitigt Hindernisse"}, {"text": "Maximale Fehler", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Qualität", "correct": false, "because": "Fördert Standards"}]');
